var b=UnityEngine.Object.FindFirstObjectByType<TownStudy.Builder.BuilderController>();var camera=b.view;var original=camera.transform.position;int checks=0;if(camera.orthographic||UnityEngine.Vector3.Angle(camera.transform.forward,UnityEngine.Vector3.forward)>.01f)throw new System.Exception("Unexpected projection");try{foreach(float height in new[]{3f,7.15f,18f}){camera.transform.position=new UnityEngine.Vector3(original.x,original.y,-height/UnityEngine.Mathf.Tan(camera.fieldOfView*.5f*UnityEngine.Mathf.Deg2Rad));for(int x=-10;x<=10;x++)for(int y=0;y<16;y++){var screen=camera.WorldToScreenPoint(new UnityEngine.Vector3(x,y,0));if(!b.ScreenCell(screen,out var actual)||actual!=new UnityEngine.Vector2Int(x,y))throw new System.Exception("Projection mismatch");checks++;}}}finally{camera.transform.position=original;}var result="PASS perspective FOV="+camera.fieldOfView+"; projection roundtrips="+checks+"; camera="+original;System.IO.File.WriteAllText("Reports/perspective-verification.txt",result);return result;
